def clean(df):
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df['flipper_length_mm'] = df['flipper_length_mm'].astype(float)
    df['species'] = df['species'].replace({'Adeile': 'Adelie', 'Gentto': 'Gentoo'})
    df['island'] = df['island'].replace({'biscoe': 'Biscoe'})
    return df

def answer(df):
    df = df.groupby('species')['body_mass_g'].mean().reset_index()
    return dict(zip(df['species'], df['body_mass_g']))
